import React, { useEffect, useState } from "react";

export default function MarketInsights() {
  const [houses, setHouses] = useState([]);
  const [lands, setLands] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");

  useEffect(() => {
    async function load() {
      try {
        const [h, l] = await Promise.all([
          fetch(`${process.env.REACT_APP_BACKEND_URL}/buy/houses`).then(r => r.json()),
          fetch(`${process.env.REACT_APP_BACKEND_URL}/buy/lands`).then(r => r.json())
        ]);
        setHouses(Array.isArray(h) ? h : []);
        setLands(Array.isArray(l) ? l : []);
      } catch (e) {
        setErr("Failed to load insights");
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  function avg(arr) {
    const vals = arr.map(x => Number(x.actualPrice)).filter(v => !isNaN(v) && v > 0);
    if (!vals.length) return null;
    return Math.round(vals.reduce((a,b)=>a+b,0)/vals.length);
  }

  const houseAvg = avg(houses);
  const landAvg = avg(lands);

  return (
    <div className="page insights">
      <h2>Market Insights</h2>
      {loading ? <div>Loading...</div> : err ? <div className="error">{err}</div> : (
        <>
          <div className="cards">
            <div className="card">
              <h3>Avg Listed House Price</h3>
              <p>{houseAvg ? `₹${houseAvg.toLocaleString("en-IN")}` : "Not enough data"}</p>
            </div>
            <div className="card">
              <h3>Avg Listed Land Price</h3>
              <p>{landAvg ? `₹${landAvg.toLocaleString("en-IN")}` : "Not enough data"}</p>
            </div>
            <div className="card">
              <h3>Total House Listings</h3>
              <p>{houses.length}</p>
            </div>
            <div className="card">
              <h3>Total Land Listings</h3>
              <p>{lands.length}</p>
            </div>
          </div>

          <h4>Recent Areas</h4>
          <ul className="list">
            {houses.slice(0,5).map(h => (
              <li key={`h-${h.id}`}>House • {h.city || h.location || "Unknown"}</li>
            ))}
            {lands.slice(0,5).map(l => (
              <li key={`l-${l.id}`}>Land • {l.city || l.location || "Unknown"}</li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}
